 final Runnable ticker=new Runnable(){public void run(){if(!visible)return;if(Store.tick(MainActivity.this,state)){if(Store.ringing(state))startForegroundService(new Intent(MainActivity.this,RingService.class));build();}for(Runnable r:new ArrayList<>(refresh))r.run();handler.postDelayed(this,250);}};
 @Override public void onCreate(Bundle b){super.onCreate(b);state=Store.load(this);page=b==null?state.optInt("page"):b.getInt("page");if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},7);build();}
